const std = @import("std");

pub fn main() !void {
    const celsius = [_]f64{ 0.0, 25.0, 100.0 };

    for (celsius) |c| {
        const f = c * 9.0 / 5.0 + 32.0;
        std.debug.print("{d}C = {d}F\n", .{c, f});
    }
}

